def build_profile(name, age=None):
    profile = {"name": name, "age": age}
    profile["has_age"] = age is not None
    return profile

print(build_profile("Ada", 27))

def parse_limit(raw_value):
    cleaned = raw_value.strip()
    if not cleaned:
        return 10
    return int(cleaned)

print(parse_limit(" 25 "))

def paginate(item_count, page_size):
    full_pages, remainder = divmod(item_count, page_size)
    return full_pages + (1 if remainder else 0)

print(paginate(53, 10))

def can_publish(user):
    valid_role = user.get("role") in {"editor", "admin"}
    return valid_role and user.get("active", False)

print(can_publish({"role": "editor", "active": True}))

from math import isclose

def reached_target(progress, target):
    return isclose(progress, target, rel_tol=1e-9)

print(reached_target(0.1 + 0.2, 0.3))

def first_valid(values):
    for raw in values:
        if cleaned := raw.strip():
            return cleaned
    return None

print(first_valid(["  ", "  Python  "]))
